import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);

        long E = sc.nextLong();
        long S = sc.nextLong();
        long L = sc.nextLong();

        long menor = Math.min(E, Math.min(S, L));
        long maior = Math.max(E, Math.max(S, L));

        long resposta = 2L * (maior - menor);

        System.out.println(resposta);
    }
}
